def ensure_dirs():
    for d in DIRS:
        (BASE / d).mkdir(parents=True, exist_ok=True)


def make_note(category: str, title: str, desc: str, stages: list,
              factors: list, examples: list, related: str, death_factors: list) -> str:
    stages_md = "\n".join(f"  - {s}" for s in stages)
    factors_md = "\n".join(f"  - {f}" for f in factors)
    examples_md = "\n".join(f"  - {e}" for e in examples)
    death_md = "\n".join(f"  - {f}" for f in death_factors)
    return f"""---
type: {category}
tags: [evolution]
---
# {title}
## Описание
{desc}
## Стадии
{stages_md}
## Факторы развития
{factors_md}
## Факторы смерти
{death_md}
## Примеры
{examples_md}
## Связи
- {related}
"""


def pick_related(category, idx, total):
    """Создать плотные кросс-ссылки между заметками."""
    links = []
    # Ссылки на соседние заметки в той же категории
    if idx > 0:
        links.append(f"[[{DIRS[DIRS.index(category.capitalize())]}_{idx-1:03d}]]")
    if idx < total - 1:
        links.append(f"[[{DIRS[DIRS.index(category.capitalize())]}_{idx+1:03d}]]")
    return links


def generate_notes():
    all_notes = {}
    categories = {
        "Origins": ORIGINS,
        "Mutations": MUTATIONS,
        "Adaptations": ADAPTATIONS,
        "Competitions": COMPETITIONS,
        "Selections": SELECTIONS,
        "Extinctions": EXTINCTIONS,
        "Rebirths": REBIRTHS,
    }

    for cat_name, data in categories.items():
        all_notes[cat_name] = []
        for i, (title, desc, stages, factors, examples, related, death_factors) in enumerate(data):
            fname = f"{cat_name}_{i:03d}.md"
            content = make_note(cat_name.lower(), title, desc, stages, factors, examples, related, death_factors)
            all_notes[cat_name].append((fname, title, content))
            fpath = BASE / cat_name / fname
            fpath.write_text(content, encoding="utf-8")
            print(f"  {fpath.relative_to(BASE)}")

    return all_notes


def generate_moc(all_notes):
    lines = ["---", "type: moc", "tags: [evolution, moc]", "---", "# EvolutionGraph", "", "## Категории", ""]
    for cat_name in DIRS:
        lines.append(f"### {cat_name}")
        for fname, title, _ in all_notes[cat_name]:
            lines.append(f"- [[{cat_name}/{fname.replace('.md', '')}|{title}]]")
        lines.append("")

    lines.append("## Связи между категориями")
    lines.append("- Origins -> Mutations -> Competitions -> Selections -> Adaptations")
    lines.append("- Failure -> Extinctions -> Rebirths")
    lines.append("")

    (BASE / "MOC EvolutionGraph.md").write_text("\n".join(lines), encoding="utf-8")
    print("  MOC EvolutionGraph.md")


def generate_global_moc(all_notes):
    lines = ["---", "type: moc", "tags: [evolution, global, moc]", "---", "# MOC Global", ""]

    for cat_name in DIRS:
        lines.append(f"## {cat_name}")
        for fname, title, _ in all_notes[cat_name]:
            lines.append(f"- [[{cat_name}/{fname.replace('.md', '')}|{title}]]")
        lines.append("")

    (BASE / "MOC Global.md").write_text("\n".join(lines), encoding="utf-8")
    print("  MOC Global.md")


